package com.jagan.healthcare.controller;
import com.jagan.healthcare.dto.DoctorRequest; import com.jagan.healthcare.model.Doctor; import com.jagan.healthcare.repository.DoctorRepository; import com.jagan.healthcare.security.SessionAuth; import com.jagan.healthcare.service.DoctorService; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/doctors") @CrossOrigin(origins="*") public class DoctorController { private final DoctorRepository repository; private final DoctorService doctorService; public DoctorController(DoctorRepository repository,DoctorService doctorService){this.repository=repository;this.doctorService=doctorService;} @GetMapping public List<Doctor> getDoctors(@RequestParam(required=false) String hospital,@RequestParam(required=false) String specialty){ if(hospital!=null&&!hospital.isBlank()&&specialty!=null&&!specialty.isBlank()) return repository.findBySpecialtyContainingIgnoreCaseAndHospitalNameIgnoreCase(specialty,hospital); if(hospital!=null&&!hospital.isBlank()) return repository.findByHospitalNameIgnoreCase(hospital); if(specialty!=null&&!specialty.isBlank()) return repository.findBySpecialtyContainingIgnoreCase(specialty); return repository.findAll(); } @PostMapping public Doctor create(@Valid @RequestBody DoctorRequest r,HttpSession session){SessionAuth.requireAdmin(session);return doctorService.create(r);} @PutMapping("/{id}") public Doctor update(@PathVariable Long id,@Valid @RequestBody DoctorRequest r,HttpSession session){SessionAuth.requireAdmin(session);return doctorService.update(id,r);} @DeleteMapping("/{id}") public Map<String,String> delete(@PathVariable Long id,HttpSession session){SessionAuth.requireAdmin(session);doctorService.delete(id);return Map.of("message","Doctor deleted.");} }
